refentry.refsect1:
&reftitle.description;
boolarray_any arrayarray callablecallback
array_any restituisce &true; se la callback fornita restituisce &true; per almeno un elemento. In caso contrario la funzione restituisce &false;.

  &reftitle.examples;

   Esempio di array_any


<?php
$array = [
    'a' => 'dog',
    'b' => 'cat',
    'c' => 'cow',
    'd' => 'duck',
    'e' => 'goose',
    'f' => 'elephant'
];

// Verifica se almeno un nome di animale è più lungo di 5 lettere.
var_dump(array_any($array, function (string $value) {
    return strlen($value) > 5;
}));

// Verifica se almeno un nome di animale è più corto di 3 lettere.
var_dump(array_any($array, function (string $value) {
    return strlen($value) < 3;
}));

// Verifica se almeno una chiave dell'array non è una stringa.
var_dump(array_any($array, function (string $value, $key) {
   return !is_string($key);
}));
?>


   &example.outputs;


bool(true)
bool(false)
bool(false)
